int err = 0;
lfs_block_t block = LFS_BLOCK_NULL;
uint8_t *lookahead = static_cast<uint8_t*>(lfs->cfg->lookahead_buffer);
lfs_size_t i, n = lfs->cfg->lookahead_size * 8;

// find free block using lookahead buffer
for (i = 0; i < n; i++) {
    if (!(lookahead[i / 8] & (1 << (i % 8)))) {
        block = i;
        break;
    }
}

if (block == LFS_BLOCK_NULL) {
    // no free block found, try to allocate a new block
    for (i = 0; i < lfs->block_count; i++) {
        if (lfs->free[i]) {
            block = i;
            lfs->free[i] = 0;
            break;
        }
    }
}

if (block == LFS_BLOCK_NULL) {
    // no free block available
    return LFS_ERR_NOSPC;
}

// update lookahead buffer
lookahead[block / 8] |= (1 << (block % 8));

// update wear leveling
lfs->wear[block]++;

// store allocated block number
*block = block;

return 0;

